import { cn } from "@repo/design-system/lib/utils";

interface BoundaryCardProps {
  children: React.ReactNode;
  facts: readonly string[];
  side: "client" | "server";
  title: string;
}

/**
 * Shared chrome for the two halves of the boundary demo, so the only visible
 * difference between them is the one that matters: where they run.
 */
export function BoundaryCard({
  children,
  facts,
  side,
  title,
}: BoundaryCardProps) {
  return (
    <div className="flex h-full flex-col gap-4 rounded-xl border border-foreground/10 bg-muted/20 p-4 sm:p-5">
      <div className="flex items-center justify-between gap-3">
        <span
          className={cn(
            "inline-flex items-center rounded-full border px-2.5 py-0.5 font-mono font-semibold text-[0.65rem] uppercase tracking-[0.2em]",
            side === "server"
              ? "border-ht-cyan-700/30 text-ht-cyan-800 dark:border-ht-cyan-500/40 dark:text-ht-cyan-300"
              : "border-ht-orange-700/30 text-ht-orange-800 dark:border-ht-orange-500/40 dark:text-ht-orange-300"
          )}
        >
          {side}
        </span>
        <span className="font-mono text-muted-foreground text-xs">{title}</span>
      </div>
      <div className="flex-1">{children}</div>
      <ul className="grid gap-1 border-foreground/10 border-t pt-3 font-mono text-muted-foreground text-xs/5">
        {facts.map((fact) => (
          <li className="flex gap-2" key={fact}>
            <span aria-hidden="true" className="select-none opacity-55">
              –
            </span>
            {fact}
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";

import { useCallback, useState } from "react";
import { BoundaryCard } from "./card";

/**
 * A Client Component. The `"use client"` directive at the top of this file is
 * the entire boundary — everything imported below it ships to the browser and
 * hydrates. That's what buys you the click handler.
 */
export function ClientCard() {
  const [count, setCount] = useState(0);
  const handleClick = useCallback(() => {
    setCount((current) => current + 1);
  }, []);

  return (
    <BoundaryCard
      facts={[
        "can use state, effects, onClick",
        "ships JavaScript (that’s the deal)",
        "cannot read secrets — it lives in your tab",
      ]}
      side="client"
      title="client-card.tsx"
    >
      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-4">
          <button
            className="inline-flex items-center justify-center rounded-full border border-transparent bg-primary px-4 py-[calc(0.5rem-1px)] font-medium text-base text-primary-foreground shadow-md hover:bg-primary/90"
            onClick={handleClick}
            type="button"
          >
            Click me
          </button>
          <p className="font-display font-medium text-2xl text-foreground tabular-nums tracking-tight">
            {count}
          </p>
        </div>
        <p className="text-foreground/75 text-sm/6">
          {count === 0
            ? "This button works because this component hydrated in your browser."
            : "No server was consulted. This state lives — and dies — in your tab."}
        </p>
      </div>
    </BoundaryCard>
  );
}

