        <p className="text-foreground/75 text-sm/6">
          at {formatStamp(new Date(facts.renderedAt))}, then cached. Refresh the
          page — this card doesn&rsquo;t re-render, it gets re-served.
        </p>
      </div>
    </BoundaryCard>
  );
}

