import { requireChapter } from "../../lab/syllabus";
import { CodeBlock } from "../code-block";
import { DemoSection } from "../demo-section";
import { InlineCode } from "../inline-code";
import { LivePanel } from "../live-panel";
import { ReferenceBar } from "../reference-bar";
import { ClientCard } from "./client-card";
import { ServerCard } from "./server-card";
import { BOUNDARY_SOURCE } from "./source";

const chapter = requireChapter("boundary");

interface BoundaryDemoProps {
  headingAs?: "h1" | "h2";
}

export function BoundaryDemo({ headingAs }: BoundaryDemoProps) {
  return (
    <DemoSection
      belief={chapter.belief}
      headingAs={headingAs}
      id={`demo-${chapter.slug}`}
      intro={
        <>
          <p>
            Safer than what? We reached for it the same way, for about a year,
            before anyone made us say what it was protecting against. Every
            component in the App Router already runs on the server.{" "}
            <InlineCode>&quot;use client&quot;</InlineCode>&#32;is not a
            precaution, it&rsquo;s a purchase — for that file and everything it
            imports. You buy useState, useEffect and onClick. You pay with the
            database call you can no longer make from here, the API key you can
            no longer read, and however much React your visitor downloads on
            their phone.
          </p>
          <p>
            Watch the two cards below. One rendered in Node.js and arrived as
            finished HTML — done before you got here. The other arrived as
            JavaScript and woke up in your tab — the waking is called hydration
            — and its button is waiting for a click. Only one of them is running
            Node, and it prints the version to prove it.
          </p>
        </>
      }
      meta={
        <>
          The error that sends everyone here is &ldquo;useState only works in a
          Client Component&rdquo;. The server isn&rsquo;t being difficult. It
          has no clicks to listen for.
        </>
      }
      navLabel={chapter.navLabel}
      topic={chapter.topic}
    >
      <LivePanel
        references={
          <ReferenceBar
            docsHref="https://nextjs.org/docs/app/getting-started/server-and-client-components"
            sourceHref="https://github.com/hasToggle/hasToggle.dev/tree/main/apps/web/app/%5Blocale%5D/(playground)/boundary"
          >
            <CodeBlock
              code={BOUNDARY_SOURCE}
              file="server-card.tsx + client-card.tsx"
            />
          </ReferenceBar>
        }
      >
        <div className="flex flex-col gap-5">
          <div className="grid gap-4 sm:grid-cols-2">
            <ServerCard />
            <ClientCard />
          </div>
          {/* The seam, narrated: the one fact neither card can state alone. */}
          <p className="font-mono text-muted-foreground text-xs/5">
            props cross the boundary as serialized data — the import graph
            decides which side a component runs on.
          </p>
        </div>
      </LivePanel>
    </DemoSection>
  );
}

"use client";

import { Switch } from "@repo/design-system/components/ui/switch";
import { useState } from "react";
import { LivePanel } from "../live-panel";
import { StateCard } from "./state-card";

interface StatePanelProps {
  references: React.ReactNode;
  /** Server-highlighted source for the card's back face. */
  replayCode: React.ReactNode;
}

/**
 * The client owner of the state exhibit's chrome. The gauge stays `live`:
 * nothing here makes a server round trip — every event is a client render,
 * which is the exhibit's whole subject. No deck: the exhibit's one action
 * is the +1, and that is the specimen, not a control.
 */
export function StatePanel({ references, replayCode }: StatePanelProps) {
  const [narrate, setNarrate] = useState(false);

  const viewControls = (
    <div className="flex items-center gap-2.5">
      <label
        className="cursor-pointer select-none font-mono font-semibold text-[0.7rem] text-muted-foreground uppercase tracking-[0.2em]"
        htmlFor="state-narrate"
      >
        narrate
      </label>
      <Switch
        checked={narrate}
        id="state-narrate"
        onCheckedChange={setNarrate}
      />
    </div>
  );

  return (
    <LivePanel references={references} viewControls={viewControls}>
      <div className="flex flex-col gap-5">
        <div className="mx-auto w-full max-w-xl">
          <StateCard narrate={narrate} replayCode={replayCode} />
        </div>
        {/* The seam, narrated: the one fact the replay acts out. */}
        <p className="font-mono text-muted-foreground text-xs/5">
          a state variable is a value React keeps between calls — and setting it
          is permission to call the component again.
        </p>
      </div>
    </LivePanel>
  );
}

import { requireChapter } from "../../lab/syllabus";
import { CodeBlock } from "../code-block";
import { DemoSection } from "../demo-section";
import { InlineCode } from "../inline-code";
import { ReferenceBar } from "../reference-bar";
import { ReplayCode } from "./replay-code";
import { STATE_SOURCE } from "./source";
import { StatePanel } from "./state-panel";

const chapter = requireChapter("state");

interface StateDemoProps {
  headingAs?: "h1" | "h2";
}

export function StateDemo({ headingAs }: StateDemoProps) {
  return (
    <DemoSection
      belief={chapter.belief}
      headingAs={headingAs}
      id={`demo-${chapter.slug}`}
      intro={
        <>
          <p>
            You don&rsquo;t — for the counting. A component is a function:
            render means React calls it and paints what it returns. A{" "}
            <InlineCode>let</InlineCode> inside that function is born in the
            call and dies with it, so adding one to it works — and changes
            nothing on screen, because changing a value and repainting the
            screen are two different jobs. <InlineCode>useState</InlineCode>
            &#32;is how a counter gets both: the setter stores the value where
            React keeps it between calls, and it schedules the call — the render
            — that paints it.
          </p>
          <p>
            Press +1 and the number moves, the way counters always have. Now
            flip narrate and press again: the card turns over and replays the
            render against its own source — React runs StateCard() again, top to
            bottom, useState hands back the value it kept, and the line that
            paints the count paints the new one. Then the card turns back, and
            the number has moved. Everything in the replay happened before the
            card finished turning. It is slowed, not simulated, and the values
            in it were read live.
          </p>
        </>
      }
      meta={
        <>
          The fine print: the card can&rsquo;t actually slow React down — the
          new number existed before the card finished turning. What you&rsquo;re
          watching is a millisecond, replayed with the values it happened with.
        </>
      }
      navLabel={chapter.navLabel}
      topic={chapter.topic}
    >
      {/* The client panel owns the instrument: narrate mode and the
          re-render pass are its view state, and the +1 button stays in the
          card — it is the specimen, not a control (design.md §4). The
          replay's source arrives server-highlighted through props, so no
          highlighter ships to the browser. */}
      <StatePanel
        references={
          <ReferenceBar
            docsHref="https://react.dev/learn/state-a-components-memory"
            sourceHref="https://github.com/hasToggle/hasToggle.dev/tree/main/apps/web/app/%5Blocale%5D/(playground)/state"
          >
            <CodeBlock code={STATE_SOURCE} file="state-card.tsx" />
          </ReferenceBar>
        }
        replayCode={<ReplayCode />}
      />
    </DemoSection>
  );
}

