interface ServerFacts {
  nodeVersion: string;
  renderedAt: string;
}

// biome-ignore lint/suspicious/useAwait: `use cache` only works on async functions, even when nothing awaits
async function getServerFacts(): Promise<ServerFacts> {
  "use cache";
  cacheLife("hours");
  return {
    nodeVersion: process.version,
    renderedAt: new Date().toISOString(),
  };
}

/**
 * The rest beat's body: a Server Component, rendered in Node and passed
 * through the client panel as a finished slot — props crossing the
 * boundary as serialized data, which is the chapter's own mechanism.
 * `process.version` is proof of residence: browsers don't have one.
 */
export async function ServerCard() {
  const facts = await getServerFacts();

  return (
    <div className="flex flex-col gap-2">
      <p className="font-display font-medium text-2xl text-foreground tracking-tight">
        Rendered in Node.js{" "}
        <span className="text-ht-cyan-700 dark:text-ht-cyan-300">
          {facts.nodeVersion}
        </span>
      </p>
      <p className="text-foreground/75 text-sm/6">
        at {formatStamp(new Date(facts.renderedAt))}, then cached. Refresh the
        page — this card doesn&rsquo;t re-render, it gets re-served.
      </p>
    </div>
  );
}

"use client";

import { useCallback, useState } from "react";
import { InlineCode } from "../inline-code";

/**
 * The hydrated beat's body: the same card after the directive claimed it.
 * The counter is real client state — no server is consulted — and the
 * first line reports what moving here cost: the Node globals are gone.
 */
export function ClientCard() {
  const [count, setCount] = useState(0);
  const handleClick = useCallback(() => {
    setCount((current) => current + 1);
  }, []);

  return (
    <div className="flex flex-col gap-2">
      <p className="font-display font-medium text-2xl text-foreground tracking-tight">
        Rendered in{" "}
        <span className="text-ht-orange-800 dark:text-ht-orange-300">
          your browser
        </span>
      </p>
      <p className="text-foreground/75 text-sm/6">
        <InlineCode>process</InlineCode>&#32;is not defined here — the Node
        version, the timestamp and the cache left with it.
      </p>
      <div className="flex items-center gap-4 pt-1">
        <button
          className="inline-flex items-center justify-center rounded-full border border-transparent bg-primary px-4 py-[calc(0.5rem-1px)] font-medium text-base text-primary-foreground shadow-md hover:bg-primary/90"
          onClick={handleClick}
          type="button"
        >
          Click me
        </button>
        <p className="font-display font-medium text-2xl text-foreground tabular-nums tracking-tight">
          {count}
        </p>
      </div>
    </div>
  );
}

